    src = [row[:] for row in grid]
    out = [row[:] for row in grid]

    centers = [(r, c, src[r][c])
               for r in range(h) for c in range(w)
               if src[r][c] not in (0, 3)]

    # An uncolored plus marks a column where horizontal rays leave a gap.
    gap_cols = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (src[r][c] == 0 and src[r-1][c] == src[r+1][c]
                    == src[r][c-1] == src[r][c+1] == 3):
                gap_cols.add(c)

    # Extend outward from each colored center, stepping past its adjacent
    # spoke marker. Other 3s stop the ray. Draw horizontal before vertical.
    for r, c, color in centers:
        for dc in (-1, 1):
            j = c + 2 * dc
            while 0 <= j < w:
                if src[r][j] == 3:
                    break
                if j not in gap_cols:
                    out[r][j] = color
                j += dc

    for r, c, color in centers:
        for dr in (-1, 1):
            i = r + 2 * dr
            while 0 <= i < h:
                if src[i][c] == 3:
                    break
                out[i][c] = color
                i += dr

    return out
